final class Sensor {
    private let handle: OpaquePointer

    init(path: String) throws {
        guard let h = path.withCString({ sensor_open($0) }) else { throw SensorError.openFailed }
        handle = h
    }

    deinit { sensor_close(handle) }        // the facade owns the native handle
}
